// components/OrderConfirmation1/buildOrderSummaryPDF.js
//
// Draws the Hose360 "Order Summary" PDF directly with jsPDF (text + shapes), instead of
// screenshotting HTML with html2canvas. Why: html2canvas stretched the logo (ignores object-fit),
// put text low inside fixed-height boxes, and its canvas read-back can stall in DuckDuckGo.
//
// Pure function: no DOM, no canvas. Input is plain data, output is an ArrayBuffer.
// Layout numbers mirror the old on-screen styles (800px wide design, dark #4a4a4a, yellow #ffc100).

const { jsPDF } = require('jspdf');

const DARK = [74, 74, 74];
const YELLOW = [255, 193, 0];
const PANEL = [245, 245, 245];
const RULE = [224, 224, 224];

const PAGE_W = 800;
const MARGIN = 20;
const CAP = 0.718; // Helvetica cap-height / font size: used to centre text optically

// Standard PDF fonts only cover WinAnsi; swap anything else for '?' rather than printing garbage.
const safe = (v) =>
  String(v == null ? '' : v).replace(/[^\x20-\x7E\xA0-\xFF–—‘’“”•€]/g, '?');

const money = (v) => {
  if (typeof v === 'number') return `A$${v.toFixed(2)}`;
  const s = String(v);
  return /^\d+(\.\d+)?$/.test(s) ? `A$${s}` : s; // bare "3.11" -> "A$3.11"
};

/**
 * @param {Object} p
 * @param {Object} p.orderData        order snapshot (selectedHose, quantity, end1Shape, ...)
 * @param {string} p.orderNumber      e.g. "PWA-1794350906460"
 * @param {number} p.baseHosePrice    price shown beside CUT LENGTHS
 * @param {number} p.displayPrice     total (ex GST)
 * @param {Uint8Array} [p.logoPng]    logo PNG bytes (optional; PDF still works without)
 * @param {number} [p.logoRatio]      logo width/height, default 800/313
 * @param {number} [p.year]
 * @returns {ArrayBuffer}
 */
function buildOrderSummaryPDF({ orderData, orderNumber, baseHosePrice, displayPrice, logoPng, logoRatio = 800 / 313, year }) {
  // ---- rows -------------------------------------------------------------------------------
  const rows = [];
  const o = orderData;
  rows.push({ label: 'ORDER NUMBER', text: orderNumber });
  if (o.selectedHose) {
    rows.push({
      label: 'HOSE SIZE',
      text: typeof o.selectedHose === 'object' && o.selectedHose.size ? o.selectedHose.size : o.selectedHose,
    });
  }
  if (o.quantity) rows.push({ label: 'QUANTITY', text: o.quantity });
  if (o.end1Shape && o.end1Size) {
    rows.push({ label: o.isOrderFittingMode ? 'FITTING' : 'END1', text: `${o.end1Shape} - ${o.end1Size}`, price: o.end1Price });
  }
  if (o.end2Shape && o.end2Size) rows.push({ label: 'END2', text: `${o.end2Shape} - ${o.end2Size}`, price: o.end2Price });
  if (o.selectedAngle) rows.push({ label: 'ANGLE', text: o.selectedAngle });
  if (o.cutLengths && o.cutLengths.length > 0) {
    rows.push({
      label: 'CUT LENGTHS',
      cuts: o.cutLengths.map((c) => `${c.length} ${c.unit || 'mm'}`),
      price: Number(baseHosePrice).toFixed(2),
    });
  }
  if (o.selectedProtection) {
    rows.push({
      label: 'PROTECTION',
      text: o.selectedProtection,
      price: o.selectedProtection === 'NOT REQUIRED' ? 'NOT REQUIRED' : o.protectionCost,
    });
  }
  if (o.selectedPressure) {
    rows.push({
      label: 'PRESSURE TEST',
      text: o.selectedPressure,
      price: o.selectedPressure === 'Not Required' ? 'NOT REQUIRED' : o.pressureTestPrice,
    });
  }

  // ---- geometry ---------------------------------------------------------------------------
  const boxX = MARGIN;
  const boxW = PAGE_W - MARGIN * 2; // 760
  const innerX = boxX + 15; // box padding
  const innerW = boxW - 30; // 730
  const GAP = 10;
  const labelW = (innerW - GAP) / 3;
  const itemX = innerX + labelW + GAP;
  const itemW = innerW - labelW - GAP;
  const BORDER = 4;
  const PAD = 15;
  const PILL_H = 34;
  const ROW_MIN = 58;
  const ROW_GAP = 10;

  const logoH = logoPng ? 400 / logoRatio : 0;
  const logoBlock = logoPng ? MARGIN + logoH + 30 : MARGIN;
  const HEADER_H = 54;

  // Measure first (needs a scratch doc for text widths / wrapping).
  const measure = new jsPDF({ unit: 'pt', format: [PAGE_W, 1000] });
  measure.setFont('helvetica', 'bold');

  rows.forEach((r) => {
    if (r.price !== undefined && r.price !== null && r.price !== '') {
      measure.setFontSize(14);
      r.priceStr = safe(money(r.price));
      r.pillW = Math.max(100, measure.getTextWidth(r.priceStr) + 24);
    }
    const textMaxW = itemW - BORDER * 2 - PAD * 2 - (r.pillW ? r.pillW + 10 : 0);
    measure.setFontSize(16);
    if (r.cuts) {
      r.lines = r.cuts.map((c) => safe(c));
      r.h = Math.max(ROW_MIN, PAD * 2 + BORDER * 2 + r.cuts.length * 24 + (r.cuts.length - 1) * 10);
    } else {
      r.lines = measure.splitTextToSize(safe(r.text), textMaxW);
      r.h = Math.max(ROW_MIN, PAD * 2 + BORDER * 2 + r.lines.length * 20);
    }
  });

  const rowsH = rows.reduce((s, r) => s + r.h + ROW_GAP, 0);
  const TOTAL_H = 90;
  const boxH = HEADER_H + 15 + rowsH + TOTAL_H + 0;
  const footerH = 20 + 14 + 10 + 14 + 14; // rule gap + two lines
  const pageH = Math.ceil(logoBlock + boxH + 30 + footerH + MARGIN);

  // ---- draw -------------------------------------------------------------------------------
  const doc = new jsPDF({ unit: 'pt', format: [PAGE_W, pageH], compress: true });
  doc.setFont('helvetica', 'bold');

  // Draws one line of text optically centred (by cap height) on cy; align 'left'|'center'.
  const textAt = (str, x, cy, size, color, align = 'left') => {
    doc.setFontSize(size);
    doc.setTextColor(color[0], color[1], color[2]);
    doc.text(str, x, cy + (CAP * size) / 2, { align, baseline: 'alphabetic' });
  };
  const roundRect = (x, y, w, h, r, style) => doc.roundedRect(x, y, w, h, Math.min(r, h / 2, w / 2), Math.min(r, h / 2, w / 2), style);

  // Logo, centred, true aspect ratio (this is what used to come out stretched).
  if (logoPng) {
    doc.addImage(logoPng, 'PNG', (PAGE_W - 400) / 2, MARGIN, 400, logoH, undefined, 'FAST');
  }

  // Panel
  const boxY = logoBlock;
  doc.setFillColor(...PANEL);
  doc.setDrawColor(...DARK);
  doc.setLineWidth(2);
  roundRect(boxX, boxY, boxW, boxH, 15, 'FD');

  // Header band (rounded top corners: draw a rounded rect then square off its bottom half)
  doc.setFillColor(...DARK);
  roundRect(boxX, boxY, boxW, HEADER_H, 15, 'F');
  doc.rect(boxX, boxY + HEADER_H / 2, boxW, HEADER_H / 2, 'F');
  textAt('Order Summary', PAGE_W / 2, boxY + HEADER_H / 2, 20, [255, 255, 255], 'center');

  // Rows
  let y = boxY + HEADER_H + 15;
  rows.forEach((r) => {
    const cy = y + r.h / 2;

    // label pill
    doc.setFillColor(...DARK);
    roundRect(innerX, y, labelW, r.h, 25, 'F');
    textAt(safe(r.label), innerX + labelW / 2, cy, 16, [255, 255, 255], 'center');

    // bordered item
    doc.setDrawColor(...DARK);
    doc.setLineWidth(BORDER);
    roundRect(itemX + BORDER / 2, y + BORDER / 2, itemW - BORDER, r.h - BORDER, 25, 'S');

    const tx = itemX + BORDER + PAD;
    if (r.cuts) {
      const stackH = r.cuts.length * 24 + (r.cuts.length - 1) * 10;
      let ry = cy - stackH / 2;
      r.lines.forEach((line, i) => {
        const ccy = ry + 12;
        doc.setFillColor(...DARK);
        doc.circle(tx + 12, ccy, 12, 'F');
        textAt(String(i + 1), tx + 12, ccy, 14, [255, 255, 255], 'center');
        textAt(line, tx + 24 + 10, ccy, 16, DARK, 'left');
        ry += 34;
      });
    } else {
      const lh = 20;
      const top = cy - (r.lines.length * lh) / 2;
      r.lines.forEach((line, i) => textAt(safe(line), tx, top + lh / 2 + i * lh, 16, DARK, 'left'));
    }

    // price pill
    if (r.pillW) {
      const px = itemX + itemW - BORDER - PAD - r.pillW;
      doc.setFillColor(...YELLOW);
      doc.setDrawColor(...DARK);
      doc.setLineWidth(2);
      roundRect(px, cy - PILL_H / 2, r.pillW, PILL_H, 15, 'FD');
      textAt(r.priceStr, px + r.pillW / 2, cy, 14, DARK, 'center');
    }

    y += r.h + ROW_GAP;
  });

  // Total band (full inner width, flat edges like the screen)
  const totalY = y;
  doc.setFillColor(...YELLOW);
  doc.rect(innerX, totalY, innerW, TOTAL_H - 15, 'F');
  doc.setDrawColor(...DARK);
  doc.setLineWidth(2);
  doc.line(innerX, totalY, innerX + innerW, totalY);
  textAt('Total Price (Ex. GST)', PAGE_W / 2, totalY + 26, 18, DARK, 'center');
  textAt(`A$${Number(displayPrice).toFixed(2)}`, PAGE_W / 2, totalY + 56, 24, DARK, 'center');

  // Footer
  const fy = boxY + boxH + 30;
  doc.setDrawColor(...RULE);
  doc.setLineWidth(1);
  doc.line(MARGIN, fy, PAGE_W - MARGIN, fy);
  doc.setFont('helvetica', 'normal');
  textAt('For enquiries: 03 4720 3323 | info@fluidpowergroup.com.au', PAGE_W / 2, fy + 34, 14, DARK, 'center');
  textAt(`FluidPower Group © ${year || new Date().getFullYear()}`, PAGE_W / 2, fy + 58, 14, DARK, 'center');

  return doc.output('arraybuffer');
}

module.exports = { buildOrderSummaryPDF };
